-- PT105-S1-Q22. Batch 12.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch12$PT105-S1-Q22$batch12$ AND q.stimulus=$batch12$Editorial: Supporters of the proposed law that would require bicyclists to wear helmets are seriously misguided. The number of pedestrians who die yearly as a result of accidents involving automobiles is five times the number of deaths resulting from bicycle accidents, and drunken driving exacts a much higher toll than both combined. Yet there are no calls for a ban on alcohol or walking down the street.$batch12$ AND q.prompt=$batch12$Which one of the following exhibits a pattern of flawed reasoning most similar to that in the argument above?$batch12$ AND q.correct_choice=$batch12$B$batch12$) THEN RAISE EXCEPTION 'Question changed: PT105-S1-Q22'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch12$PT105-S1-Q22$batch12$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT105-S1-Q22'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch12$PT105-S1-Q22$batch12$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch12$Conclusion$batch12$, $batch12$Supporters of a bicycle helmet law are misguided.$batch12$), (1, $batch12$Evidence$batch12$, $batch12$Walking and drunk driving cause far more deaths, yet nobody calls for banning walking or alcohol.$batch12$), (2, $batch12$Evaluate$batch12$, $batch12$The editorial rejects a safety measure for one risk because bigger risks elsewhere aren't banned. But the comparison is to banning whole activities, not to a modest safety rule. A bigger risk going unaddressed doesn't make the smaller rule foolish.$batch12$), (3, $batch12$Goal$batch12$, $batch12$Find an argument that rejects a safety rule because bigger risks elsewhere aren't met with bans.$batch12$)) v(position,label,body) WHERE q.qid=$batch12$PT105-S1-Q22$batch12$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch12$A$batch12$, $batch12$This says pilots will likely die of something else first. It doesn't point to bigger risks that go unbanned.$batch12$), ($batch12$B$batch12$, $batch12$Goggles for lab workers are called foolish because more people get sick from food and disease, and nobody suggests banning eating or socializing. Same move.$batch12$), ($batch12$C$batch12$, $batch12$This argues about the right order of learning. No risk comparison.$batch12$), ($batch12$D$batch12$, $batch12$This is about timing and cost. A reasonable objection, not the original's flaw.$batch12$), ($batch12$E$batch12$, $batch12$This narrows the rule to those at risk. It doesn't reject a rule by pointing to bigger unbanned risks.$batch12$)) v(letter,body) WHERE q.qid=$batch12$PT105-S1-Q22$batch12$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
